import { React, useState } from "react";
import cat1 from "./Images/Cats/cat1.png";
import "./App.css";

export default function Cat({addToCart}) {
    
    return (
        <div className="gallery">
            <div>
                <img src={cat1} alt="cat1" />
            </div>
            <div className="desc">Ginger Cat($10)</div>
            <div className="desc">
                ${total}
            </div>
            <div className="desc">
                <span style={{ marginRight: "20px" }}>
                    M
                    <button onClick={() => setMale(Math.max(0, male - 1))}>-</button>
                    {male}
                    <button onClick={() => setMale(male + 1)}>+</button>
                </span>
                <span>
                    F
                    <button onClick={() => setFemale(Math.max(0, female - 1))}>-</button>
                    {female}
                    <button onClick={() => setFemale(female + 1)}>+</button>
                </span>
            </div>
            <div className="desc">
                <button onClick={() => addToCart(male, female, total)}>Add to cart</button>
            </div>

        </div>
    )
}
